export function init(api){const {esc,course:currCourse,route:currRoute,resume:currResume,progress:currProgress,lesson:currLesson,mapRoute:currMapRoute,currentLesson:currCurrentLesson,work:currWork,quizKey:currQuizKey,paragraphs:currParagraphs,prose:currProse,canAdvance:currCanAdvance}=api;
function currHub(){const currCatalogue=api.catalogue(),state=api.state(),currPack=api.pack();return `<header class="a-page-head"><span class="eyebrow">APPRENDRE · PRATIQUER · CONSTRUIRE</span><h1>Apprendre à coder</h1><p>Des cours organisés par modules, en français. Choisis ton objectif et avance à ton rythme.</p></header><div class="curr-course-grid">${currCatalogue.courses.map(c=>`<article class="panel curr-course-card"><span class="eyebrow">${c.availability==='premiere-serie'?'PREMIÈRE SÉRIE · SUITE EN PRÉPARATION':'DÉBUTANT'} · ${c.modules.length} MODULES</span><h2>${esc(c.title_fr)}</h2><p>${esc(c.summary_fr)}</p><small>${c.lessons.length} leçons · ${c.exercise_count} exercices · ≈ ${(c.estimated_minutes/60).toFixed(1)} h</small><a class="primary" href="#/apprendre/${c.id}">Voir le programme →</a><a class="text-button" href="${currRoute(currResume(c))}">Reprendre ou commencer →</a></article>`).join('')}</div><details class="panel"><summary>Les prochaines séries</summary><ul class="curr-ladder curr-ladder-soon">${currCatalogue.plans.map(c=>`<li><strong>${esc(c.title_fr)}</strong><span>${esc(c.summary_fr)}</span><small>En préparation</small></li>`).join('')}</ul></details><section class="panel"><h2>Ton point de départ</h2><p>Quelques préférences peuvent conseiller un programme. Tu peux aussi choisir librement.</p><button class="secondary" data-onboarding="preferences">Personnaliser mon programme</button><h2>Conserver ton travail</h2><p>Les sauvegardes restent sur cet appareil. Exporte-les avant de changer de navigateur.</p><button class="secondary" data-curr="export">Exporter ma progression de code</button><label class="curr-import">Restaurer une sauvegarde<input type="file" id="curr-import" accept="application/json"></label></section>`}
function currMap(){const currCatalogue=api.catalogue(),state=api.state(),currPack=api.pack();const c=currCourse();return `<div class="a-crumb"><a href="#/apprendre">Apprendre à coder</a> / ${esc(c.title_fr)}</div><header class="a-path-hero"><span class="eyebrow">DÉBUTANT · ${c.modules.length} MODULES · ${c.lessons.length} LEÇONS</span><h1>${esc(c.title_fr)}</h1><p>${esc(c.summary_fr)}</p><span class="a-badge">Contenu original · relecture en cours</span><div class="a-hero-actions"><a class="primary" href="${currRoute(currResume(c))}">Commencer ou reprendre →</a><button class="secondary" data-curr="download">Emporter ce cours</button></div>${currProgress(c)}</header><div class="a-detail-columns"><section class="panel"><h2>À la fin, tu sauras…</h2><ul>${c.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="panel"><h2>Ton point de départ</h2><ul>${c.prerequisites.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>≈ ${(c.estimated_minutes/60).toFixed(1)} h de pratique indicative · ${Math.ceil(JSON.stringify(currPack).length/1024)} Ko de cours${c.runtime==='python'?' · moteur Python facultatif ≈ 12 Mo':''}.</small></section></div><p class="curr-unlock-note">Tous les chapitres sont consultables. Lis le chapitre et réussis son mini-quiz pour valider tes acquis. Un test de 5 questions permet de valider un module que tu connais déjà.</p>${c.modules.map((m,i)=>`<section class="panel curr-module"><header><span class="a-stage-number">${i+1}</span><div><h2>${esc(m.title_fr)}</h2><p>${esc(m.outcome_fr||'Comprendre, pratiquer et vérifier ses acquis.')} · ${m.lesson_ids.length} leçons</p></div></header><ol class="curr-outline">${m.lesson_ids.map((id,j)=>{const l=currLesson(id);return `<li><a href="${currRoute(id)}"><span>${state.curriculum.completed[id]?'✓':j+1}</span><span>${esc(l.title_fr)}<small>${l.minutes} min · lire, pratiquer, comprendre</small></span><span>→</span></a></li>`}).join('')}</ol><a class="text-button" href="#/apprendre/${c.id}/${m.id}/validation">Je connais déjà · test de 5 questions →</a></section>`).join('')}${c.later_modules?.length?'<details class="panel"><summary>Suite du programme en préparation</summary><ul>'+c.later_modules.map(title=>'<li>'+esc(title)+'</li>').join('')+'</ul></details>':''}<p>Les temps sont des repères de pratique. La relecture pédagogique de ces contenus reste en cours.</p>`}

function currQuizPanel(l){const state=api.state(),currMode=api.mode();const key=currQuizKey(l),index=Math.min(state.curriculum.quizPositions[key]||0,l.quiz.length-1),q=l.quiz[index],a=state.curriculum.quiz[q.id],mayMove=currMode==='validation'?a?.checked:a?.correct;return `<p class="a-practice-position">Question ${index+1} sur ${l.quiz.length} · ${l.quiz.filter(q=>state.curriculum.quiz[q.id]?.correct).length} bonnes réponses</p><fieldset><legend tabindex="-1">${esc(q.question)}</legend>${api.choiceOrder(q.options,q.id).map(({value:o,index:j})=>`<label><input type="radio" name="${q.id}" data-curr-quiz="${q.id}" value="${j}" ${a?.value===j?'checked':''}>${esc(o)}</label>`).join('')}<button class="secondary" data-curr="quiz" data-id="${q.id}">Vérifier ma réponse</button>${a?.checked?`<p class="curr-feedback" role="status">${a.correct?'✓ Bien vu.':'Relis cette idée puis réessaie.'} ${esc(q.explanation)}</p>`:''}</fieldset><div class="curr-actions"><button class="secondary" data-curr="quiz-prev" ${index?'':'disabled'}>← Question précédente</button>${index<l.quiz.length-1?`<button class="primary" data-curr="quiz-next" ${mayMove?'':'disabled'}>Question suivante →</button>`:'<button class="secondary" data-curr="quiz-summary">Voir le bilan de la leçon ↓</button>'}</div>`}
function currTestDescription(test){if(test.checks)return esc(test.description_fr);return `${test.inputs?.length?'Saisies : '+esc(test.inputs.join(', '))+' · ':''}${test.calls?.length?'Appels : '+test.calls.map(c=>`<code>${esc(c.name)}(${esc(JSON.stringify(c.args).slice(1,-1))})</code> → ${esc(JSON.stringify(c.expected))}`).join(' · '):'Affichage attendu : <pre>'+esc(test.expected_output)+'</pre>'}`}
function currLessonView(){const state=api.state(),currMode=api.mode(),currTab=api.tab(),currFeedback=api.feedback(),currRunning=api.running();let currActiveExercise=api.exercise();
 const l=currCurrentLesson(),c=currCourse();if(!l)return '<h1>Leçon introuvable</h1><a href="'+currMapRoute()+'">Voir le programme</a>';
 const m=c.modules.find(x=>x.id===l.module),i=m.lesson_ids.indexOf(l.id),web=['html','css'].includes(c.runtime);
 currActiveExercise=Math.min(currActiveExercise,l.exercises.length-1);api.setExercise(currActiveExercise);const ex=l.exercises[currActiveExercise],w=currWork(ex);
 return `<nav class="a-crumb" aria-label="Où suis-je ?"><a href="#/apprendre">Apprendre</a> › <a href="${currMapRoute()}">${esc(c.title_fr)}</a> › Module ${l.module.slice(1)} · ${esc(m.title_fr)} › ${currMode==='validation'?'Validation':'Leçon '+(i+1)+' sur '+m.lesson_ids.length}</nav>
 <header class="curr-lesson-head"><span class="eyebrow">${currMode==='validation'?'POINT D’ÉTAPE':l.minutes+' MIN · DEPUIS ZÉRO'}</span><h1>${esc(l.title_fr)}</h1><span class="a-badge">Contenu original · relecture en cours</span><details><summary>Plan du module · Où suis-je ?</summary><ol>${m.lesson_ids.map(id=>`<li><a href="${currRoute(id)}" ${id===l.id?'aria-current="page"':''}>${state.curriculum.completed[id]?'✓ ':''}${esc(currLesson(id).title_fr)}</a></li>`).join('')}</ol></details></header>
 <nav class="curr-mobile-tabs" aria-label="Vue de la leçon"><button data-curr="read" aria-pressed="${currTab==='read'}">Comprendre</button><button data-curr="code" aria-pressed="${currTab==='code'}">Pratiquer et tester</button></nav>
 <div class="curr-workspace" data-tab="${currTab}"><article class="curr-reading panel"><h2>Objectif</h2><ul>${l.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><strong>Prérequis :</strong> ${l.prerequisites.length?l.prerequisites.map(id=>`<a href="${currRoute(id)}">${esc(currLesson(id)?.title_fr||id)}</a>`).join(' · '):'Aucune connaissance de programmation.'}</p>
 <section class="curr-idea"><h2>L’idée en 30 secondes</h2><p>${esc(l.idea_fr)}</p><p>${esc(l.analogy_fr)}</p></section><h2>Explication pas à pas</h2>${l.body_fr.flatMap(currParagraphs).map(x=>`<p>${currProse(x,l.glossary)}</p>`).join('')}
 ${currMode==='validation'?'':l.examples.map((e,j)=>`<section class="curr-example"><h2>Exemple guidé ${j+1}</h2><pre><code>${esc(e.code)}</code></pre><h3>Ligne par ligne</h3><ol>${e.trace_fr.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h3>Résultat attendu</h3><pre>${esc(e.expected_output)}</pre></section>`).join('')}
 <section><h2>Erreurs fréquentes</h2>${l.common_mistakes.map(x=>`<details><summary>${esc(x.error)}</summary><p><strong>Pourquoi ?</strong> ${esc(x.why_fr)}</p><p><strong>Comment corriger ?</strong> ${esc(x.fix_fr)}</p></details>`).join('')}</section><section id="curr-quiz"><h2>Mini-quiz · vérifie ta compréhension</h2>${currQuizPanel(l)}</section><section><h2>Récapitulatif</h2><ul>${l.recap_fr.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section id="curr-lexicon"><h2>Mots nouveaux</h2><dl>${l.glossary.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.definition)}</dd>`).join('')}</dl></section></article>
 <aside class="curr-practice panel"><div class="curr-exercise-picker"><label>Exercice<select id="curr-exercise">${l.exercises.map((e,j)=>`<option value="${j}" ${j===currActiveExercise?'selected':''}>${state.curriculum.work[e.id]?.passed?'✓ ':''}${j+1}. ${esc(e.title_fr)}</option>`).join('')}</select></label><small>Exercice ${currActiveExercise+1} sur ${l.exercises.length} · ${l.exercises.filter(e=>state.curriculum.work[e.id]?.passed).length} réussis</small></div><h2>${esc(ex.title_fr)}</h2><p>${esc(ex.instruction_fr)}</p>${l.environment_fr?'<small>'+esc(l.environment_fr)+'</small>':''}
 ${web&&ex.fixture_html?`<details><summary>Le HTML fourni pour cet exercice</summary><pre><code>${esc(ex.fixture_html)}</code></pre></details>`:''}<div id="curr-editor-host"><label for="curr-editor">Ton code ${esc(c.language)}</label><textarea id="curr-editor" spellcheck="false" maxlength="12000" rows="10">${esc(w.code)}</textarea></div>
 <div class="curr-charbar" aria-label="Caractères utiles">${[':', '(', ')', '[', ']', '{', '}', '"', "'", '=', '#','<','>'].map(x=>`<button data-curr="insert" data-char="${esc(x)}" aria-label="Insérer ${esc(x)}">${esc(x)}</button>`).join('')}</div>
 ${web?'':`<details><summary>Saisies du programme · une réponse par ligne</summary><label for="curr-inputs">Tes réponses pour l’essai</label><textarea id="curr-inputs" rows="3">${esc((ex.visible_tests[0]?.inputs||[]).join('\n'))}</textarea></details>`}
 <div class="curr-actions"><button class="primary" data-curr="verify" ${currRunning?'disabled':''}>${currRunning?'Vérification…':'Vérifier mon code'}</button><button class="secondary" data-curr="run" ${currRunning?'disabled':''}>${web?'Voir le résultat':'Exécuter librement'}</button><button class="secondary" data-curr="stop">Arrêter</button></div><div class="curr-actions"><button class="text-button" data-curr="reset">Réinitialiser</button><button class="text-button" data-curr="hint">Voir l’indice (${w.hints}/3)</button>${w.attempts>=2?'<button class="text-button" data-curr="solution">Voir une solution</button>':'<small>Une solution est disponible après deux tentatives.</small>'}</div><div id="curr-result" role="status" aria-live="polite">${currFeedback}</div><div id="curr-preview" ${web?'':'hidden'}></div>
 ${w.hints?`<div class="curr-hint"><strong>Indice ${w.hints}</strong><p>${esc(ex.hints[Math.min(w.hints-1,2)])}</p></div>`:''}<section><h3>Ce que les tests vérifient</h3><ol>${ex.visible_tests.map(t=>`<li>${currTestDescription(t)}</li>`).join('')}</ol>${ex.hidden_tests.length?`<small>${ex.hidden_tests.length} cas supplémentaires vérifient d’autres valeurs ou situations.</small>`:''}</section>
 <div class="curr-actions"><button class="secondary" data-curr="exercise-prev" ${currActiveExercise?'':'disabled'}>← Exercice précédent</button><button class="primary" data-curr="exercise-next" ${w.passed?'':'disabled'}>${currActiveExercise<l.exercises.length-1?'Exercice suivant →':'Passer au mini-quiz →'}</button></div>
 ${c.runtime!=='python'?'':`<details><summary>Si le moteur ne démarre pas</summary><p>Le texte et le quiz restent accessibles. Le moteur Python facultatif s’enregistre séparément (≈ 12 Mo). Le calcul est arrêté après 8 secondes.</p><button class="secondary" data-curr="download-engine">Enregistrer le moteur hors ligne</button></details>`}<button class="text-button" data-curr="download-code">Télécharger mon code</button></aside></div>
 <footer class="curr-footer panel"><div><p>Lis ce chapitre et réussis le mini-quiz pour continuer. Les exercices t’aident à pratiquer.</p><div class="curr-actions"><button class="text-button" data-curr="difficulty" data-value="hard">Trop difficile</button><button class="text-button" data-curr="difficulty" data-value="easy">Trop facile</button><span>${state.curriculum.feedback[l.id]?'Avis gardé sur cet appareil.':''}</span></div></div><button class="primary" data-curr="next" ${currCanAdvance(l)?'':'disabled'}>${currMode==='validation'?'Valider le module':'Leçon suivante'} →</button></footer>`;
}
return {hub:currHub,map:currMap,lesson:currLessonView};}
